import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CWvfYWS8.js";import"./chunks/assets.Bz7j3IzC.js";var i=JSON.parse(`{"title":"创建和组织 cgroup","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ch002.md","filePath":"zh/ch002.md"}`),a={name:`zh/ch002.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="创建和组织-cgroup" tabindex="-1">创建和组织 cgroup <a class="header-anchor" href="#创建和组织-cgroup" aria-label="Permalink to “创建和组织 cgroup”">​</a></h1><p>最初，只有根 cgroup 存在，所有进程都属于它。你可以通过添加子目录来创建一个空的子 cgroup：</p><div class="language-bash" dir="ltr"><button title="复制代码" data-copied="已复制" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cg1</span></span></code></pre></div><p>每个 cgroup 都有一个名为 cgroup.procs 的接口文件，其中列出属于该 cgroup 的所有进程的 PID，每行一个。通过将某个进程的 PID 写入该 cgroup 的 cgroup.procs 文件，可以将该进程移动到该 cgroup：</p><div class="language-bash" dir="ltr"><button title="复制代码" data-copied="已复制" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24982</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cg1/cgroup.procs</span></span></code></pre></div><p>单次写调用只能迁移一个进程。如果一个进程由多个线程组成，写入任意线程的 PID 会迁移该进程的所有线程。</p><div class="warning custom-block"><p>注意：一个进程同一时间只能位于一个 cgroup 中。</p></div><h2 id="设计-cgroup-层级" tabindex="-1">设计 cgroup 层级 <a class="header-anchor" href="#设计-cgroup-层级" aria-label="Permalink to “设计 cgroup 层级”">​</a></h2><p>控制器可以在从根到叶子的任意 cgroup 中启用。每个控制器会根据自身配置以及层级中各子树的配置，沿层级分配其对应的系统资源。</p><p>你可以使用每个 cgroup（包括根 cgroup 及其所有子 cgroup）中都会出现的两个接口文件来指定控制器：</p><table tabindex="0"><thead><tr><th style="text-align:left;">文件</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;">cgroup.controllers</td><td style="text-align:left;">列出 cgroup 中可用的控制器。在根 cgroup 中，它列出系统上所有可用的控制器。在子 cgroup 中，它列出其父 cgroup 的 cgroup.subtree_control 文件中指定的控制器（见下文）。</td></tr><tr><td style="text-align:left;">cgroup.subtree_control</td><td style="text-align:left;">列出该 cgroup 的子树中处于活动状态（已启用）的控制器。这里列出的控制器是可供后代 cgroup 使用的控制器；它们会出现在后代 cgroup 的 cgroup.controllers 文件中。</td></tr></tbody></table><p>你可以通过将控制器名称写入 cgroup.subtree_control 来激活或停用控制器，每个名称前加上加号（+）表示启用，或减号（-）表示停用，如下例所示：</p><div class="language-bash" dir="ltr"><button title="复制代码" data-copied="已复制" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;+cpu -memory&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cg1/cgroup.subtree_control</span></span></code></pre></div><p>在下图中，每个 cgroup.subtree_control 文件决定其子 cgroup 可用的控制器集合，即出现在其子 cgroup 的 cgroup.controllers 文件中的控制器。</p><p><img src="/p002/ch00/002.png" alt="" width="720" height="405"></p><p>在此示例中，根 cgroup 将资源分配给两个分区：运行系统进程的 system.slice，以及通常运行生产工作负载应用的 workload.slice。对于包含 crond.service 或 smc_proxy.service 等服务子 cgroup，其可用资源控制器集合会进一步受到各自父 cgroup 的 cgroup.subtree_control 文件限制。</p><h2 id="fbtax2-cgroup-层级" tabindex="-1">fbtax2 cgroup 层级 <a class="header-anchor" href="#fbtax2-cgroup-层级" aria-label="Permalink to “fbtax2 cgroup 层级”">​</a></h2><div class="danger custom-block"><p>fbtax2 项目使用的 cgroup 层级与上图类似，但引入了一些额外的结构和最佳实践。</p><p>它将层级划分为三个顶级 cgroup，每个都有各自的用途。除了运行系统二进制程序的 system.slice cgroup 之外，它还包括：</p><ul><li><code>hostcritical.slice</code></li><li><code>workload.slice</code></li></ul><p><img src="/p002/ch00/003.png" alt="" width="716" height="226"></p><h4 id="hostcritical-slice" tabindex="-1">hostcritical.slice <a class="header-anchor" href="#hostcritical-slice" aria-label="Permalink to “hostcritical.slice”">​</a></h4><p>此 cgroup 保护维持主机运行所需的进程。它包含关键的主机管理功能，例如 sshd，以及 <a href="./ch012.html#oomd-memory-pressure-based-oom">oomd</a>——系统 OOM（内存不足） killer 的替代方案，我们将在本案例研究的<a href="./ch012.html#oomd-in-the-fbtax2-project">后续章节</a>中介绍。</p><h4 id="workload-slice" tabindex="-1">workload.slice <a class="header-anchor" href="#workload-slice" aria-label="Permalink to “workload.slice”">​</a></h4><p>保护主工作负载免受与系统二进制程序的资源冲突，是该项目的首要目标，这也是 workload.slice 的主要目的。在此案例中，主工作负载拥有自己的子 cgroup workload-container.slice，用于保护 hhvm。</p><p>另一个子 cgroup workload-support.slice 为维持主工作负载运行所需的一些系统二进制程序提供保护。例如，如果 workload-support.service 等二进制程序失败，主工作负载也可能失败。工作负载所需的具体系统二进制程序集合以及分配给它们的资源量会因上下文而异。但将所需二进制程序保护在 workload-support.slice 这样的 cgroup 中，有助于确保它们可用，从而维持主工作负载运行。</p><p>在本案例研究的<a href="./ch003.html#memory-pressure-in-the-fbtax2-project">下一节</a>中，我们将了解 <strong>fbtax2</strong> 如何使用 PSI 内存压力指标。</p></div><h2 id="关于-cgroup-层级的补充说明" tabindex="-1">关于 cgroup 层级的补充说明 <a class="header-anchor" href="#关于-cgroup-层级的补充说明" aria-label="Permalink to “关于 cgroup 层级的补充说明”">​</a></h2><p>所有控制器行为都是层级化的：如果你在某个 cgroup 上启用控制器，它会影响属于其子层级中所有 cgroup 的所有进程。</p><p>同样，你可以在 cgroup 中查询的大多数统计信息，例如当前内存或 CPU 使用量，显示的是整个子树的合计值。</p><p>在层级中越靠近根设置的限制，无法从更远处覆盖。当你在嵌套 cgroup 上启用控制器时，它总是会进一步限制资源分配。</p><div class="warning custom-block"><p>注意：子 cgroup 消耗的资源总和不能超过父 cgroup 可用的资源总量。</p></div><h3 id="避免父-cgroup-与子-cgroup-之间的资源冲突" tabindex="-1">避免父 cgroup 与子 cgroup 之间的资源冲突 <a class="header-anchor" href="#避免父-cgroup-与子-cgroup-之间的资源冲突" aria-label="Permalink to “避免父 cgroup 与子 cgroup 之间的资源冲突”">​</a></h3><p>为消除子 cgroup 与其父 cgroup 内部进程争抢资源的情况，cgroup 只有在自身不包含任何进程时，才能控制向子 cgroup 分配内存和 IO。换句话说，cgroup 可以包含任务，或为子 cgroup 控制资源，但不能两者兼有。</p><div class="warning custom-block"><p class="custom-block-title"></p><p>注意：此规则的例外是根 cgroup，它既可以包含进程，也可以控制资源分配。</p></div><p>因此，如果父 cgroup 控制向一个或多个子 cgroup 分配资源（即其 cgroup.subtree_control 文件非空），则父 cgroup 中的任何进程都必须移动到它们自己的子 cgroup 中。</p><p>例如，像 /cg1/cg2 这样的 cgroup 可以包含进程，但如果 /cg1 自身也包含任何进程，则这些进程应移动到它们自己的叶子节点，例如 /cg1/cg3。</p><p>对于某些遗留配置，CPU 控制器也可以既包含进程又控制资源分配。详情请参阅 <a href="http://man7.org/linux/man-pages/man7/cgroups.7.html" target="_blank" rel="noreferrer">cgroup 手册页</a> 中关于线程模式的章节。</p><h2 id="其他有用的-cgroup-接口文件" tabindex="-1">其他有用的 cgroup 接口文件 <a class="header-anchor" href="#其他有用的-cgroup-接口文件" aria-label="Permalink to “其他有用的 cgroup 接口文件”">​</a></h2><p>这些 cgroup 接口文件在设计和测试 cgroup 层级时很有用：</p><table tabindex="0"><thead><tr><th style="text-align:left;">文件</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cgroup.events</code></td><td style="text-align:left;">包含标识 cgroup 状态或事件的键/值对。<br> <br> 事件或状态变化会生成 file-modified 事件，使应用程序能够跟踪和监控变化。<br> <br> populated 字段指示该 cgroup 或其任何后代是否包含活动进程：1 表示该 cgroup 和/或其子 cgroup 包含活动进程；0 表示没有活动进程。</td></tr><tr><td style="text-align:left;"><code>cgroup.max.depth</code></td><td style="text-align:left;">指定后代 cgroup 嵌套深度的限制。0 表示不能创建后代 cgroup。默认值为 <code>max</code>。</td></tr><tr><td style="text-align:left;"><code>cgroup.max.descendants</code></td><td style="text-align:left;">指定一个 cgroup 可拥有的后代 cgroup 数量限制。向此文件写入字符串 <code>max</code> 表示不施加限制。默认值为 <code>max</code>。</td></tr></tbody></table>`,32)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};